      <label id="ai-resend-history-option" hidden><input id="ai-resend-history" type="checkbox">\u4EE5\u524D\u306E\u8CC7\u6599\u3082\u5168\u6587\u3067\u9001\u308A\u76F4\u3059</label>
      <button id="ai-preview-button" type="button">\u9001\u4FE1\u5185\u5BB9\u3092\u78BA\u8A8D</button>
    </fieldset>
